import{_ as o,o as d,c,a2 as a}from"./chunks/framework.mqZn2l2k.js";const m=JSON.parse('{"title":"附录 D 练习参考答案","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/d-answers.md","filePath":"appendix/d-answers.md","lastUpdated":1791458539000}'),i={name:"appendix/d-answers.md"};function l(t,e,r,n,s,h){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="附录-d-练习参考答案" tabindex="-1">附录 D 练习参考答案 <a class="header-anchor" href="#附录-d-练习参考答案" aria-label="Permalink to &quot;附录 D 练习参考答案&quot;">​</a></h1><blockquote><p>巩固题给出完整答案；扩展题给出实现要点或思路；读源码题给出定位和结论。答案不唯一，能讲清“为什么”就行。</p></blockquote><h2 id="第-0-章" tabindex="-1">第 0 章 <a class="header-anchor" href="#第-0-章" aria-label="Permalink to &quot;第 0 章&quot;">​</a></h2><ol><li>JSON 里只有 <code>nodes</code>（节点数组）和 <code>connections</code>（按源节点索引的连接），没有坐标以外的布局信息——图就是这两样东西。</li><li>v0.1 的 <code>npm test</code> 跑引擎的核心能力：线性执行、分支、错误、表达式。数一下 <code>it(...)</code> 的个数，对照每个测试名里的能力。</li><li>If 节点最新版类名是 <code>IfV2</code>（<code>packages/nodes-base/nodes/If/V2/IfV2.node.ts</code>）。</li></ol><h2 id="第-1-章" tabindex="-1">第 1 章 <a class="header-anchor" href="#第-1-章" aria-label="Permalink to &quot;第 1 章&quot;">​</a></h2><ol><li>Workflow 是<strong>确定性</strong>的、步骤固定的流程；Agent 由模型<strong>在运行时决定</strong>调用哪些工具。前者适合“每天同步订单到表格”，后者适合“根据用户问题自己查资料再回答”。</li><li>把“判断金额、超过 1000 就走审批、否则直接退款”做成确定性工作流（IF + Human Approval），把“理解用户诉求、决定要不要退款”交给 Agent。关键是<strong>钱的决定不交给模型</strong>。</li><li><code>grep &#39;&quot;tools/&#39; packages/@n8n/nodes-langchain/package.json | wc -l</code>，数 <code>n8n.nodes</code> 里 <code>dist/nodes/tools/</code> 开头的条目。</li></ol><h2 id="第-2-章" tabindex="-1">第 2 章 <a class="header-anchor" href="#第-2-章" aria-label="Permalink to &quot;第 2 章&quot;">​</a></h2><ol><li>依赖方向：<code>editor-ui → cli → core → nodes-base → workflow</code>，<code>workflow</code> 在最底层，不依赖任何其他包。</li><li><code>n8n-nodes-base</code> 依赖 <code>n8n-core</code> 会造成循环依赖，也会让社区节点被绑死在某个 core 内部实现上；core 一变，所有节点都可能崩。节点只应依赖 <code>n8n-workflow</code> 的接口。</li><li>有 <code>executionData</code> 时走 <code>processRunExecutionData</code>（恢复一个已有执行）；没有时走 <code>run</code>（全新执行）。</li></ol><h2 id="第-3-章" tabindex="-1">第 3 章 <a class="header-anchor" href="#第-3-章" aria-label="Permalink to &quot;第 3 章&quot;">​</a></h2><ol><li>六步大致是：REST 控制器 → WorkflowExecutionService → WorkflowRunner → WorkflowExecute（引擎）→ 各节点的 execute → 生命周期钩子（存库 + 推送）。</li><li>在 <code>nodeExecuteBefore</code> 钩子里 <code>console.log</code> 节点名，在 <code>workflowExecuteBefore</code> 记开始时间、<code>workflowExecuteAfter</code> 打印 <code>Date.now() - start</code>。</li><li><code>hookFunctionsSaveProgress</code> 在 <code>saveExecutionProgress</code> 开启时生效，挂在 <code>nodeExecuteAfter</code> 上，每个节点执行完就把当前 runData 存库——崩溃后能看到执行到哪一步。</li></ol><h2 id="第-4-章" tabindex="-1">第 4 章 <a class="header-anchor" href="#第-4-章" aria-label="Permalink to &quot;第 4 章&quot;">​</a></h2><ol><li><code>connections</code> 里 Code 连两个 Set（同一个输出接两条边），两个 Set 各连 Merge 的不同输入。<code>npm run mini-n8n -- execute --file</code> 跑它。</li><li><code>renameNode</code> 要改 <code>nodes</code> 的键、<code>connectionsBySourceNode</code> 和 <code>connectionsByDestinationNode</code> 两份索引。进阶：遍历所有节点参数，把 <code>$(&#39;old&#39;)</code> / <code>$node[&quot;old&quot;]</code> 改成新名，注意别动字符串字面量里的同名文本。</li><li>n8n 的 <code>depth</code> 控制向上追几层。菱形依赖下，去重后两种实现返回的节点集合一致，但顺序可能不同（取决于遍历是深度优先还是广度优先）。</li></ol><h2 id="第-5-章" tabindex="-1">第 5 章 <a class="header-anchor" href="#第-5-章" aria-label="Permalink to &quot;第 5 章&quot;">​</a></h2><ol><li><code>Filter</code> 节点：<code>execute</code> 里遍历 items，<code>evaluateCondition</code> 为真的保留，输出时 <code>pairedItem: { item: i }</code> 指回原下标。</li><li>在 <code>displayParameter</code> 里，若依赖的参数值是以 <code>=</code> 开头的表达式字符串，直接返回 true（显示）。测一个“依赖参数是表达式时字段照常显示”的用例。</li><li>If 节点有 V1、V2 两个大版本，V2 的条件参数 <code>type</code> 是 <code>filter</code>。</li></ol><h2 id="第-6-章" tabindex="-1">第 6 章 <a class="header-anchor" href="#第-6-章" aria-label="Permalink to &quot;第 6 章&quot;">​</a></h2><ol><li>第二个 Set 用 <code>$(&#39;Code&#39;).item.json.amount</code> 把被第一个 Set 丢掉的金额取回来——<code>$(...)</code> 能引用任意已执行节点的、与当前条目配对的输出。</li><li>在 AST 层把 <code>x.isEmpty()</code> 改写成 <code>__extend(x, &#39;isEmpty&#39;, [])</code>，<code>__extend</code> 里先判断 <code>x</code> 是否已有该方法，有就调原方法，没有才用扩展实现，避免误伤。</li><li>isolate 里用 lazy proxy：表达式访问 <code>$json.foo</code> 时，proxy 通过桥接回宿主进程按需取值，而不是一开始就把整个数据复制进 isolate。</li></ol><h2 id="第-7-章" tabindex="-1">第 7 章 <a class="header-anchor" href="#第-7-章" aria-label="Permalink to &quot;第 7 章&quot;">​</a></h2><ol><li>v1 深度优先：If 的 true 分支（2 条）先一路走到 Merge，再回头走 false 分支；Merge 等两个输入到齐后执行，最后 Code。用 mini-n8n 打印 <code>lastNodeExecuted</code> 序列验证。</li><li>让 Merge 的输入 1 连在一个“没有被任何上游触发”的 Set 上：v1 会追祖先、触发那个 Set；v0 不追，Merge 永远等不齐。</li><li>部分执行从“脏节点，或缺少运行数据的节点”开始；<code>findStartNodes</code> 沿着到目标节点的子图往回找这些起点。</li></ol><h2 id="第-8-章" tabindex="-1">第 8 章 <a class="header-anchor" href="#第-8-章" aria-label="Permalink to &quot;第 8 章&quot;">​</a></h2><ol><li>改成 <code>continueRegularOutput</code> 后，Validate 出错的条目带着原输入继续往下走（而不是进错误分支）。</li><li>在重试判断里，若节点返回的条目只有 <code>error</code> 字段，视为失败、触发重试。测一个“第一次返回 error、第二次成功”的用例。</li><li>如果失败工作流就是它自己，n8n 会跳过（不触发），避免无限递归。</li></ol><h2 id="第-9-章" tabindex="-1">第 9 章 <a class="header-anchor" href="#第-9-章" aria-label="Permalink to &quot;第 9 章&quot;">​</a></h2><ol><li><code>runData</code> 存这次执行的实际数据，<code>workflowData</code> 存执行时的工作流快照。改工作流后旧执行的 <code>workflowData</code> 不变——执行是历史快照。</li><li>启动时和每小时删 <code>stoppedAt</code> 早于 N 小时的执行。这正是第 28 章实现的 <code>ExecutionsPruning</code>，可对照。</li><li>软删除只打标记（<code>deletedAt</code>），到硬删除缓冲期后真正删行；二进制数据存在文件系统/对象存储里，不随行删除，要单独清理。</li></ol><h2 id="第-10-章" tabindex="-1">第 10 章 <a class="header-anchor" href="#第-10-章" aria-label="Permalink to &quot;第 10 章&quot;">​</a></h2><ol><li><code>EventSource</code> 建立 SSE 连接后，curl 带 <code>push-ref: t1</code> 触发执行，控制台会依次打印 <code>executionStarted</code>、各节点的 <code>nodeExecuteAfter</code>、<code>executionFinished</code>。</li><li><code>nodeExecuteAfter</code> 只发 <code>itemCount</code>，数据单独走 <code>nodeExecuteAfterData</code>；超过 1 MB 时不发数据，前端在执行结束后用 <code>GET /rest/executions/:id</code> 拉全量。</li><li><code>websocket.push.ts</code> 用定时 ping，客户端回 pong；连续没收到 pong 就判定连接已死、清理掉。</li></ol><h2 id="第-11-章" tabindex="-1">第 11 章 <a class="header-anchor" href="#第-11-章" aria-label="Permalink to &quot;第 11 章&quot;">​</a></h2><ol><li>建 <code>httpBasicAuth</code> 凭证填 user/pass，HTTP Request 选该凭证，调 httpbin 的 basic-auth 端点返回 200 即通。</li><li><code>POST /rest/credentials/test</code>：解密凭证 → 跑 <code>authenticate</code> → 按凭证类型的 <code>test</code> 规则发请求 → 返回 <code>{ status, message }</code>。</li><li><code>credential-domain-restrictions.ts</code> 校验请求目标域名是否在凭证允许的域名列表里，不在就拒绝——防止凭证被节点发往任意地址。</li></ol><h2 id="第-12-章" tabindex="-1">第 12 章 <a class="header-anchor" href="#第-12-章" aria-label="Permalink to &quot;第 12 章&quot;">​</a></h2><ol><li>Webhook（responseNode）→ If（看 <code>body.vip</code>）→ 两个 Respond to Webhook，一个返回 200 一个返回 403。</li><li><code>poll()</code> 支持：激活时按 <code>pollInterval</code> 定时调用 <code>poll()</code>，用 <code>getWorkflowStaticData(&#39;node&#39;)</code> 存上次游标，返回非空就启动执行。</li><li>lastNode 模式下，响应哪个节点由 <code>lastNodeExecuted</code> 决定，取其最后一次运行、第一个 item；n8n 可通过 Respond When 等参数配置。</li></ol><h2 id="第-13-章" tabindex="-1">第 13 章 <a class="header-anchor" href="#第-13-章" aria-label="Permalink to &quot;第 13 章&quot;">​</a></h2><ol><li>改连后 <code>connections</code> 里 If 的第 2 个输出（index 1）从原目标变成新的 NoOp 节点。</li><li>每种操作写成 <code>{ do(), undo() }</code> 命令，压入一个栈；Ctrl+Z 弹栈调 <code>undo()</code>，重做用另一个栈。</li><li><code>renameNode</code> 调 <code>renameNodeInParameterValue</code> 递归遍历参数，正则匹配 <code>$(&#39;old&#39;)</code>、<code>$node[&quot;old&quot;]</code> 等形式；要小心字符串里的引号转义，避免破坏用户的字面量。</li></ol><h2 id="第-14-章" tabindex="-1">第 14 章 <a class="header-anchor" href="#第-14-章" aria-label="Permalink to &quot;第 14 章&quot;">​</a></h2><ol><li>URL 表达式预览会实时显示代入 <code>$json.id</code> 后的字符串；Method 切 Expression 后按金额返回 POST/GET。</li><li><code>preview(value, itemIndex)</code> 多接一个下标，表格行悬停时传入该行下标，预览按该条目求值。</li><li>自动补全候选来自上游节点的运行数据和推断出的 schema（字段名、类型）。</li></ol><h2 id="第-15-章" tabindex="-1">第 15 章 <a class="header-anchor" href="#第-15-章" aria-label="Permalink to &quot;第 15 章&quot;">​</a></h2><ol><li>pin 住 Orders 后，即使把它的代码改成抛异常，执行也直接用钉住的数据、不真正运行它，所以不报错——pin data 优先级高于执行。</li><li>起始节点在循环体内时，把起点改成 Loop 节点本身（循环入口），否则会从环中间开始、状态不对。参考 <code>handle-cycles.ts</code>。</li><li>该起始节点被放在它那个有运行数据的父节点的下游位置，作为重建执行栈的起点。</li></ol><h2 id="第-16-章" tabindex="-1">第 16 章 <a class="header-anchor" href="#第-16-章" aria-label="Permalink to &quot;第 16 章&quot;">​</a></h2><ol><li>Session Key 固定成 <code>&quot;global&quot;</code> 后，两个会话共享同一段记忆、互相看到对方的消息——会话隔离失效。</li><li>“Window Buffer Memory (SQLite)”：<code>supplyData</code> 返回的记忆对象把消息读写到数据库表（按 session key），重启后仍在。</li><li>供应商不返回 token 用量时，<code>N8nLlmTracing</code> 用分词器估算 prompt 和 completion 的 token 数。</li></ol><h2 id="第-17-章" tabindex="-1">第 17 章 <a class="header-anchor" href="#第-17-章" aria-label="Permalink to &quot;第 17 章&quot;">​</a></h2><ol><li>Basic LLM Chain + Ollama，执行后模型节点 NDV 能看到发出的 messages（system + user）和响应。</li><li><code>OpenAICompatibleChatModel</code> 遇 429/5xx 按 1s/2s/4s 退避重试最多 3 次；用本地假服务器先返回 429 再返回 200 来测。</li><li>限制响应大小必须在 fetch 层（边读边数字节、超限就中断），否则恶意/异常的大响应在“拿到完整响应再检查”之前就已经把内存吃光了。</li></ol><h2 id="第-18-章" tabindex="-1">第 18 章 <a class="header-anchor" href="#第-18-章" aria-label="Permalink to &quot;第 18 章&quot;">​</a></h2><ol><li>Max Iterations=1 时，第一次模型调用请求工具，但引擎还没来得及给出结果就达到了迭代上限，第二次（本应处理工具结果）之前就报错。</li><li>最终输出带 <code>intermediateSteps</code>（每步的工具名、输入、输出），编辑器输出面板用表格展示。</li><li><code>saveToMemory()</code> 把带工具调用的一轮合并保存；<code>previousCount</code> 用来跳过已经存过的历史消息，只存新增的。</li></ol><h2 id="第-19-章" tabindex="-1">第 19 章 <a class="header-anchor" href="#第-19-章" aria-label="Permalink to &quot;第 19 章&quot;">​</a></h2><ol><li><code>executionOrder</code> 改成 v0 一般不改变工具的执行结果（工具由 EngineRequest 单独调度），但主流程里多输入节点的顺序可能变。运行验证。</li><li>工具节点设了 Timeout 时，引擎用 <code>Promise.race</code> 加超时；超时就把 <code>Error: timed out</code> 作为该工具的结果交回 Agent，不拖垮整个执行。</li><li>有 <code>parentNodeName</code>（子 Agent 的工具）时，<code>parentRunIndex</code> 取父节点已有的运行次数减一——指向父 Agent 当前这一次运行，让工具的日志挂在正确的父运行下。</li></ol><h2 id="第-20-章" tabindex="-1">第 20 章 <a class="header-anchor" href="#第-20-章" aria-label="Permalink to &quot;第 20 章&quot;">​</a></h2><ol><li>HTTP Request Tool 的 URL 用 <code>$fromAI(&#39;city&#39;, ...)</code>，问天气时模型把 <code>city</code> 填成 <code>Tokyo</code>，NDV 的输入里能看到它填的参数。</li><li>MCP Server Trigger：<code>inputs</code> 为 <code>ai_tool</code> 的 Webhook 触发器，<code>tools/list</code> 时用 <code>getInputConnectionData</code> 收集连着的工具定义返回，<code>tools/call</code> 时执行对应工具节点。</li><li><code>extractFromAICalls()</code> 用一个能处理嵌套引号和逗号的解析器（不是简单 split），正确切出 <code>$fromAI(&#39;q&#39;, &#39;a &quot;quoted&quot;, text&#39;)</code> 的各个参数。</li></ol><h2 id="第-21-章" tabindex="-1">第 21 章 <a class="header-anchor" href="#第-21-章" aria-label="Permalink to &quot;第 21 章&quot;">​</a></h2><ol><li>带 <code>-N</code> 的 curl 会看到回答逐行（逐 token）到达，而不是一次性返回——这就是流式。</li><li>Simple Memory 记每个 session 的最后访问时间，清理定时器删除超过一小时未访问的；用注入的假时钟推进时间来测。</li><li><code>responseNodes</code> 模式下，工作流里的多个 Chat/Respond 节点可以分别向聊天窗口发消息，实现“一次执行多次回复”。</li></ol><h2 id="第-22-章" tabindex="-1">第 22 章 <a class="header-anchor" href="#第-22-章" aria-label="Permalink to &quot;第 22 章&quot;">​</a></h2><ol><li>Chunk Size=40 时块数变多，每块更短，<code>chunkIndex</code> 增大、<code>itemIndex</code> 仍指原条目；检索更精细但可能丢上下文。</li><li><code>update</code> 模式按 ID 更新向量；元数据过滤在相似度排序前先按 <code>title</code> 等字段筛选。写一个“过滤后只返回 Shipping 块”的测试。</li><li><code>retrieve</code> 输出 <code>ai_vectorStore</code> 给 Question and Answer Chain，由 <strong>Chain</strong> 决定何时检索；<code>retrieve-as-tool</code> 输出 <code>ai_tool</code>，由 <strong>Agent</strong> 决定何时检索。</li></ol><h2 id="第-23-章" tabindex="-1">第 23 章 <a class="header-anchor" href="#第-23-章" aria-label="Permalink to &quot;第 23 章&quot;">​</a></h2><ol><li>点 Reject 后 Agent 回复“人类拒绝了调用”，Refund 不运行；再次打开同一链接返回 409（执行已不是 waiting）。</li><li>把 Human Approval 放子 Agent 下——mini-n8n 支持（嵌套 EngineRequest），n8n 不支持。等待时执行栈有外层 Agent、子 Agent、审批节点等多层。</li><li>审批人填反馈时，<code>getChatInput()</code> 取到反馈文本，<code>getDenialMessage()</code> 生成带反馈的消息给 Agent（而非简单“已拒绝”）。我们的实现要在等待 Webhook 里接收文本、存进节点状态、拒绝分支里带上。</li></ol><h2 id="第-24-章" tabindex="-1">第 24 章 <a class="header-anchor" href="#第-24-章" aria-label="Permalink to &quot;第 24 章&quot;">​</a></h2><ol><li>父执行显示 <code>waiting</code>（等子工作流），子执行也 <code>waiting</code>（Wait 节点）；两分钟后 WaitTracker 恢复子执行，父执行随之 <code>success</code>。</li><li><code>resumeParentsOfFinishedSubExecutions()</code>：扫描“栈顶 metadata 有 <code>waitingChildExecutionIds</code> 且那些子执行已结束”的父执行，打补丁并恢复。测“子执行先结束、父执行后置 waiting”的竞态。</li><li>等待 Webhook 恢复子执行后，在 <code>resumeParentExecution</code> 里给父执行打补丁并认领恢复——和 WaitTracker 用同一套逻辑。</li></ol><h2 id="第-25-章" tabindex="-1">第 25 章 <a class="header-anchor" href="#第-25-章" aria-label="Permalink to &quot;第 25 章&quot;">​</a></h2><ol><li><code>--concurrency 1</code> 时两个 worker 共 2 个并发槽，20 个各 0.2 秒的请求约需 2 秒（原来 10 槽约 0.5 秒）——并发槽变少，吞吐下降。</li><li>worker 每 10 秒给正在处理的任务续 Redis 锁（带过期）；main 扫 “active” 列表，锁过期的任务放回 “waiting”。<code>kill -9</code> 一个 worker，它的任务锁到期后被另一个 worker 接走。</li><li><code>job-outcome-tracker.ts</code> 在错过 <code>job-finished</code> 消息时，回查数据库里该执行的最终状态来“结案”，避免因消息丢失而永远等待。</li></ol><h2 id="第-26-章" tabindex="-1">第 26 章 <a class="header-anchor" href="#第-26-章" aria-label="Permalink to &quot;第 26 章&quot;">​</a></h2><ol><li>超时 2 秒的 <code>while(true){}</code>：约 2 秒后报 <code>Task execution timed out after 2 seconds</code>，runner 被重启，执行状态为 <code>error</code>。</li><li>给 runner 加并发：主进程用信号量限制同时在跑的任务数，超出的排队；或让一个 runner 进程并行处理多个任务。</li><li>built-ins-parser 用 acorn 静态分析代码，找出它真正引用了哪些变量（<code>$json</code>、<code>$(&#39;X&#39;)</code>…），只把这些数据发给 runner——大执行时能省下大量序列化和传输。</li></ol><h2 id="第-27-章" tabindex="-1">第 27 章 <a class="header-anchor" href="#第-27-章" aria-label="Permalink to &quot;第 27 章&quot;">​</a></h2><ol><li>setup 拿 cookie → 建 key → 用 <code>X-N8N-API-KEY</code> 调 <code>GET /api/v1/workflows</code>。只有 <code>workflow:read</code> 的 key 去 <code>POST</code> 建工作流，返回 403（缺 <code>workflow:create</code> scope）。</li><li>所有权转移：把该工作流的 <code>workflow:owner</code> 从当前用户改成目标用户。转移前确认操作者本就是 owner，别把自己变成无权访问。</li><li><code>global:member</code> 只有自己资源的 scope；在团队项目里，工作流是按项目分享的，成员看到的是“所在项目的工作流”，个人项目里则只有自己创建的。</li></ol><h2 id="第-28-章" tabindex="-1">第 28 章 <a class="header-anchor" href="#第-28-章" aria-label="Permalink to &quot;第 28 章&quot;">​</a></h2><ol><li><code>/metrics</code> 看指标；激活工作流后 <code>active_workflow_count</code> 加一；<code>MINI_N8N_LOG_FORMAT=json</code> 后日志变成每行一个 JSON。</li><li>给执行计数加 <code>workflowId</code> 标签；告警规则思路：<code>rate(失败数[5m]) / rate(总数[5m]) &gt; 0.5</code>。</li><li>n8n 的 <code>stopProcess</code> 还会关闭外部 secret 轮询、刷新未落盘的 binary data、释放 license 等——我们都省了。</li></ol><h2 id="实验室" tabindex="-1">实验室 <a class="header-anchor" href="#实验室" aria-label="Permalink to &quot;实验室&quot;">​</a></h2><ul><li><strong>Lab 1–6</strong> 的检查清单本身就是答案：每一项都能用对应的 <code>npm test</code> / <code>npm run test:e2e</code> / 示例脚本验证。卡住时，先 <code>git checkout vX.Y</code> 跑通参考实现，再 <code>git diff</code> 看它比你多做了什么。</li></ul>',62)])])}const p=o(i,[["render",l]]);export{m as __pageData,p as default};
